"""Models for the base data types."""

from enum import Enum
from typing import Any, Optional

from pydantic import BaseModel, FieldSerializationInfo, field_serializer


class ImageRefMode(str, Enum):
    """ImageRefMode."""

    PLACEHOLDER = "placeholder"  # just a place-holder
    EMBEDDED = "embedded"  # embed the image as a base64
    REFERENCED = "referenced"  # reference the image via uri


class CoordOrigin(str, Enum):
    """CoordOrigin."""

    TOPLEFT = "TOPLEFT"
    BOTTOMLEFT = "BOTTOMLEFT"


class PydanticSerCtxKey(str, Enum):
    """Pydantic serialization context keys."""

    COORD_PREC = "coord_prec"  # key for coordinates precision
    CONFID_PREC = "confid_prec"  # key for confidence values precision


def round_pydantic_float(val: float, ctx: Any, precision_ctx_key: PydanticSerCtxKey) -> float:
    """Round float, provided the precision is available in the context."""
    precision = (
        ctx.get(precision_ctx_key.value) if isinstance(ctx, dict) else getattr(ctx, precision_ctx_key.value, None)
    )
    return round(val, precision) if isinstance(precision, int) else val


class Size(BaseModel):
    """Size."""

    width: float = 0.0
    height: float = 0.0

    @field_serializer("width", "height")
    def _serialize(self, value: float, info: FieldSerializationInfo) -> float:
        return round_pydantic_float(value, info.context, PydanticSerCtxKey.COORD_PREC)

    def as_tuple(self):
        """as_tuple."""
        return (self.width, self.height)


class BoundingBox(BaseModel):
    """BoundingBox."""

    l: float  # left
    t: float  # top
    r: float  # right
    b: float  # bottom

    coord_origin: CoordOrigin = CoordOrigin.TOPLEFT

    @property
    def width(self):
        """Width."""
        return self.r - self.l

    @property
    def height(self):
        """Height."""
        return abs(self.t - self.b)

    @field_serializer("l", "t", "r", "b")
    def _serialize(self, value: float, info: FieldSerializationInfo) -> float:
        return round_pydantic_float(value, info.context, PydanticSerCtxKey.COORD_PREC)

    def resize_by_scale(self, x_scale: float, y_scale: float):
        """resize_by_scale."""
        return BoundingBox(
            l=self.l * x_scale,
            r=self.r * x_scale,
            t=self.t * y_scale,
            b=self.b * y_scale,
            coord_origin=self.coord_origin,
        )

    def scale_to_size(self, old_size: Size, new_size: Size):
        """scale_to_size."""
        return self.resize_by_scale(
            x_scale=new_size.width / old_size.width,
            y_scale=new_size.height / old_size.height,
        )

    # same as before, but using the implementation above
    def scaled(self, scale: float):
        """Scaled."""
        return self.resize_by_scale(x_scale=scale, y_scale=scale)

    # same as before, but using the implementation above
    def normalized(self, page_size: Size):
        """Normalized."""
        return self.scale_to_size(old_size=page_size, new_size=Size(height=1.0, width=1.0))

    def expand_by_scale(self, x_scale: float, y_scale: float) -> "BoundingBox":
        """expand_to_size."""
        if self.coord_origin == CoordOrigin.TOPLEFT:
            return BoundingBox(
                l=self.l - self.width * x_scale,
                r=self.r + self.width * x_scale,
                t=self.t - self.height * y_scale,
                b=self.b + self.height * y_scale,
                coord_origin=self.coord_origin,
            )
        elif self.coord_origin == CoordOrigin.BOTTOMLEFT:
            return BoundingBox(
                l=self.l - self.width * x_scale,
                r=self.r + self.width * x_scale,
                t=self.t + self.height * y_scale,
                b=self.b - self.height * y_scale,
                coord_origin=self.coord_origin,
            )

    def as_tuple(self) -> tuple[float, float, float, float]:
        """as_tuple."""
        if self.coord_origin == CoordOrigin.TOPLEFT:
            return (self.l, self.t, self.r, self.b)
        elif self.coord_origin == CoordOrigin.BOTTOMLEFT:
            return (self.l, self.b, self.r, self.t)

    @classmethod
    def from_tuple(cls, coord: tuple[float, ...], origin: CoordOrigin):
        """from_tuple.

        :param coord: tuple[float:
        :param ...]:
        :param origin: CoordOrigin:

        """
        if origin == CoordOrigin.TOPLEFT:
            l, t, r, b = coord[0], coord[1], coord[2], coord[3]
            if r < l:
                l, r = r, l
            if b < t:
                b, t = t, b

            return BoundingBox(l=l, t=t, r=r, b=b, coord_origin=origin)
        elif origin == CoordOrigin.BOTTOMLEFT:
            l, b, r, t = coord[0], coord[1], coord[2], coord[3]
            if r < l:
                l, r = r, l
            if b > t:
                b, t = t, b

            return BoundingBox(l=l, t=t, r=r, b=b, coord_origin=origin)

    def area(self) -> float:
        """Area."""
        return abs(self.r - self.l) * abs(self.b - self.t)

    def intersection_area_with(self, other: "BoundingBox") -> float:
        """Calculate the intersection area with another bounding box."""
        if self.coord_origin != other.coord_origin:
            raise ValueError("BoundingBoxes have different CoordOrigin")

        # Calculate intersection coordinates
        left = max(self.l, other.l)
        right = min(self.r, other.r)

        if self.coord_origin == CoordOrigin.TOPLEFT:
            bottom = max(self.t, other.t)
            top = min(self.b, other.b)
        elif self.coord_origin == CoordOrigin.BOTTOMLEFT:
            top = min(self.t, other.t)
            bottom = max(self.b, other.b)

        # Calculate intersection dimensions
        width = right - left
        height = top - bottom

        # If the bounding boxes do not overlap, width or height will be negative
        if width <= 0 or height <= 0:
            return 0.0

        return width * height

    def intersection_over_union(self, other: "BoundingBox", eps: float = 1.0e-6) -> float:
        """intersection_over_union."""
        intersection_area = self.intersection_area_with(other=other)

        union_area = (
            abs(self.l - self.r) * abs(self.t - self.b)
            + abs(other.l - other.r) * abs(other.t - other.b)
            - intersection_area
        )

        return intersection_area / (union_area + eps)

    def intersection_over_self(self, other: "BoundingBox", eps: float = 1.0e-6) -> float:
        """intersection_over_self."""
        intersection_area = self.intersection_area_with(other=other)
        if self.area() > 0:
            return intersection_area / self.area()
        else:
            return 0.0

    def to_bottom_left_origin(self, page_height: float) -> "BoundingBox":
        """to_bottom_left_origin.

        :param page_height:

        """
        if self.coord_origin == CoordOrigin.BOTTOMLEFT:
            return self.model_copy()
        elif self.coord_origin == CoordOrigin.TOPLEFT:
            return BoundingBox(
                l=self.l,
                r=self.r,
                t=page_height - self.t,
                b=page_height - self.b,
                coord_origin=CoordOrigin.BOTTOMLEFT,
            )

    def get_intersection_bbox(self, other: "BoundingBox") -> Optional["BoundingBox"]:
        """Return the intersection bounding box with another bounding box or ``None`` when disjoint."""
        if self.coord_origin != other.coord_origin:
            raise ValueError("BoundingBoxes have different CoordOrigin")

        left = max(self.l, other.l)
        right = min(self.r, other.r)

        if self.coord_origin == CoordOrigin.TOPLEFT:
            top = max(self.t, other.t)
            bottom = min(self.b, other.b)
            if right <= left or bottom <= top:
                return None
            return BoundingBox(l=left, t=top, r=right, b=bottom, coord_origin=self.coord_origin)

        top = min(self.t, other.t)
        bottom = max(self.b, other.b)
        if right <= left or top <= bottom:
            return None
        return BoundingBox(l=left, t=top, r=right, b=bottom, coord_origin=self.coord_origin)

    def to_top_left_origin(self, page_height: float) -> "BoundingBox":
        """to_top_left_origin.

        :param page_height:

        """
        if self.coord_origin == CoordOrigin.TOPLEFT:
            return self.model_copy()
        elif self.coord_origin == CoordOrigin.BOTTOMLEFT:
            return BoundingBox(
                l=self.l,
                r=self.r,
                t=page_height - self.t,  # self.b
                b=page_height - self.b,  # self.t
                coord_origin=CoordOrigin.TOPLEFT,
            )

    def overlaps(self, other: "BoundingBox") -> bool:
        """Overlaps."""
        return self.overlaps_horizontally(other=other) and self.overlaps_vertically(other=other)

    def overlaps_horizontally(self, other: "BoundingBox") -> bool:
        """Check if two bounding boxes overlap horizontally."""
        return not (self.r <= other.l or other.r <= self.l)

    def overlaps_vertically(self, other: "BoundingBox") -> bool:

# ---------------------------------------------------------------- assemble
def _assemble_document(self, conv_res: ConversionResult) -> ConversionResult:
    elements, headers, body = [], [], []
    with TimeRecorder(conv_res, "doc_assemble", scope=ProfilingScope.DOCUMENT):
        for p in conv_res.pages:
            if p.assembled:
                elements.extend(p.assembled.elements)
                headers.extend(p.assembled.headers)
                body.extend(p.assembled.body)
        conv_res.assembled = AssembledUnit(
            elements=elements, headers=headers, body=body
        )
        conv_res.document = self.reading_order_model(conv_res)
        conv_res.document = self.heading_hierarchy_model(conv_res)

        # Generate page images in the output
        if self.pipeline_options.generate_page_images:
            for page in conv_res.pages:
                assert page.image is not None
                page_no = page.page_no
                conv_res.document.pages[page_no].image = ImageRef.from_pil(
                    page.image, dpi=int(72 * self.pipeline_options.images_scale)
                )

        # Generate images of the requested element types
        with warnings.catch_warnings():  # deprecated generate_table_images
            warnings.filterwarnings("ignore", category=DeprecationWarning)
            if (
                self.pipeline_options.generate_picture_images
                or self.pipeline_options.generate_table_images
            ):
                scale = self.pipeline_options.images_scale
                for element, _level in conv_res.document.iterate_items():
                    if not isinstance(element, DocItem) or len(element.prov) == 0:
                        continue
                    if (
                        isinstance(element, PictureItem)
                        and self.pipeline_options.generate_picture_images
                    ) or (
                        isinstance(element, TableItem)
                        and self.pipeline_options.generate_table_images
                    ):
                        page_ix = element.prov[0].page_no
                        page = next(
                            (p for p in conv_res.pages if p.page_no == page_ix),
                            cast("Page", None),
                        )
                        assert page is not None
                        assert page.size is not None
                        assert page.image is not None

                        crop_bbox = (
                            element.prov[0]
                            .bbox.scaled(scale=scale)
                            .to_top_left_origin(
                                page_height=page.size.height * scale
                            )
                        )

                        cropped_im = page.image.crop(crop_bbox.as_tuple())
                        element.image = ImageRef.from_pil(
                            cropped_im, dpi=int(72 * scale)
                        )

        # Aggregate confidence values for document:
        if len(conv_res.pages) > 0:
            with warnings.catch_warnings():
                warnings.filterwarnings(
                    "ignore",
                    category=RuntimeWarning,
                    message="Mean of empty slice|All-NaN slice encountered",
                )
                conv_res.confidence.layout_score = float(
                    np.nanmean(
                        [c.layout_score for c in conv_res.confidence.pages.values()]
                    )
                )
                conv_res.confidence.parse_score = float(
                    np.nanquantile(
                        [c.parse_score for c in conv_res.confidence.pages.values()],
                        q=0.1,  # parse score should relate to worst 10% of pages.
                    )
                )
                conv_res.confidence.table_score = float(
                    np.nanmean(
                        [c.table_score for c in conv_res.confidence.pages.values()]
                    )
                )
                conv_res.confidence.ocr_score = float(
                    np.nanmean(
                        [c.ocr_score for c in conv_res.confidence.pages.values()]
                    )
                )

        # Add failed pages to DoclingDocument.pages to preserve page numbering
        # This ensures page break markers are generated for skipped/failed pages
        self._add_failed_pages_to_document(
            conv_res, expected_page_nos=self._get_expected_page_nos(conv_res)
        )

    return conv_res

def _add_failed_pages_to_document(
    self, conv_res: ConversionResult, expected_page_nos: list[int]
) -> None:
    """Add failed/skipped pages to DoclingDocument.pages.

    This ensures that page break markers are correctly generated for documents
    where some pages failed to parse. Without this, export functions would not
    know about the missing pages and would generate incorrect page break counts.

    The failed pages are added with their size information (if available from
    the backend) but without any content.
    """
    if conv_res.document is None:
        return

    # Find pages that are missing from the document
    existing_page_nos = set(conv_res.document.pages.keys())
    missing_page_nos = set(expected_page_nos) - existing_page_nos

    if not missing_page_nos:
        return

    for page_no in sorted(missing_page_nos):
        size = self._page_sizes_by_no.get(page_no, Size(width=0.0, height=0.0))

        # Add the failed page to the document's pages dict
        conv_res.document.pages[page_no] = PageItem(
            page_no=page_no,
            size=size,
            image=None,
        )

    _log.debug(
        "Added %d failed/skipped pages to document: %s",
        len(missing_page_nos),
        sorted(missing_page_nos),
    )

# ---------------------------------------------------------------- misc
@classmethod
def get_default_options(cls) -> ThreadedPdfPipelineOptions:
    return ThreadedPdfPipelineOptions()
